// Generated by Manus asset storage.
// Shared restoration limits for Godot preview and portable Three.js builds.
export const HYDRATION_TIMEOUT_MS = 240_000
export const RESTORE_WORKERS = 8
export const RESTORE_MAX_ATTEMPTS = 3
export const TRANSIENT_HTTP_CODES = new Set([408, 425, 429, 500, 502, 503, 504])
const transientCodes = new Set(['ECONNRESET', 'ECONNREFUSED', 'ECONNABORTED', 'EPIPE', 'ETIMEDOUT', 'EAI_AGAIN', 'ENETRESET', 'ENETUNREACH', 'EHOSTUNREACH', 'UND_ERR_SOCKET', 'UND_ERR_CONNECT_TIMEOUT', 'UND_ERR_HEADERS_TIMEOUT', 'UND_ERR_BODY_TIMEOUT'])
export function transientDownloadError(error, seen = new Set()) {
  if (!error || typeof error !== 'object' || seen.has(error)) return false
  seen.add(error)
  if (error.name === 'AbortError' || error.name === 'TimeoutError') return false
  return TRANSIENT_HTTP_CODES.has(error.status) || transientCodes.has(error.code) || transientDownloadError(error.cause, seen)
}
